    const coverTitle=x.coverTitle||(type==="event"?x.name:x.title)||"HLPB 最新消息";
    return `<div class="editorial-cover category-${encodeURIComponent(label)} ${isActivity?"editorial-cover-event":""}" aria-hidden="true"><span class="cover-kicker">${label}</span><span class="cover-title">${safe(coverTitle)}</span></div>`;
