// Share only pages with their own article or event URL.
(() => {
  const article = document.querySelector('main .article-detail');
  if (!article || !/\/(articles|news|events)\/[a-z0-9-]+\.html$/.test(location.pathname)) return;
  const meta = article.querySelector('.article-meta') || article;
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'share-page-button';
  button.textContent = '分享這篇';
  button.setAttribute('aria-label', '分享或複製文章介紹與連結');
  meta.append(button);
  button.addEventListener('click', async () => {
    const url = document.querySelector('link[rel="canonical"]')?.href || location.href;
    const title = document.querySelector('main h1')?.textContent.trim() || document.title;
    const text = `👀 這篇匹克球文章分享給你！\n${title}\n`;
    const copyText = async () => {
      await navigator.clipboard.writeText(`${text}\n${url}`);
      button.textContent = '已複製分享文字';
      setTimeout(() => { button.textContent = '分享這篇'; }, 2500);
    };
    try {
      if (navigator.share) { await navigator.share({title,text,url}); return; }
      await copyText();
    } catch (error) {
      if (error?.name !== 'AbortError') {
        try { await copyText(); }
        catch {
          button.textContent = '請使用瀏覽器分享功能';
          setTimeout(() => { button.textContent = '分享這篇'; }, 3000);
        }
      }
    }
  });
})();

// Shared back-to-top control, with reduced-motion and keyboard support.
